local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "strafelua"
Junkie.identifier = "1170309"
Junkie.provider = "strafelua"

local result = (function()
    getgenv().UI_CLOSED = false
    local genv = getgenv()

    local UIS = game:GetService("UserInputService")
    local TS = game:GetService("TweenService")

    local function hasFileSystemSupport()
        local hasWritefile = pcall(function() return type(writefile) == "function" end)
        local hasReadfile = pcall(function() return type(readfile) == "function" end)
        local hasIsfile = pcall(function() return type(isfile) == "function" end)
        return hasWritefile and hasReadfile and hasIsfile
    end

    local fileSystemSupported = hasFileSystemSupport()

    local function saveVerifiedKey(key)
        if not fileSystemSupported then return false end
        local ok = pcall(function()
            writefile("verified_key.txt", key)
        end)
        return ok
    end

    local function loadVerifiedKey()
        if not fileSystemSupported then
            return nil
        end
        local ok, content = pcall(function()
            return readfile("verified_key.txt")
        end)
        if not ok or not content then
            return nil
        end
        return content
    end

    local function clearSavedKey()
        if not fileSystemSupported then return false end
        local ok = pcall(function() delfile("verified_key.txt") end)
        return ok
    end

    local function GetUIParent()
        if gethui then return gethui() end
        return game:GetService("CoreGui")
    end

    local Parent = GetUIParent()

    for _, child in pairs(Parent:GetChildren()) do
        if child.Name == "StrafeKeyUI" then
            child:Destroy()
        end
    end

    local Theme = {
        Main = Color3.fromRGB(20, 20, 20),
        Item = Color3.fromRGB(30, 30, 30),
        Outline = Color3.fromRGB(60, 60, 60),
        Accent = Color3.fromRGB(150, 174, 222),
        Text = Color3.fromRGB(255, 255, 255),
        TextDim = Color3.fromRGB(150, 150, 150),
    }

    local UI = Instance.new("ScreenGui")
    UI.Name = "StrafeKeyUI"
    UI.IgnoreGuiInset = true
    UI.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    UI.Parent = Parent

    local Main = Instance.new("Frame")
    Main.Name = "MainFrame"
    Main.Size = UDim2.new(0, 320, 0, 225)
    Main.Position = UDim2.new(0.5, -160, 0.5, -100)
    Main.BackgroundColor3 = Theme.Main
    Main.BorderSizePixel = 0
    Main.Parent = UI
    Instance.new("UICorner", Main).CornerRadius = UDim.new(0, 10)

    local MainStroke = Instance.new("UIStroke", Main)
    MainStroke.Thickness = 1
    MainStroke.Color = Theme.Outline

    local TitleBar = Instance.new("Frame")
    TitleBar.Size = UDim2.new(1, 0, 0, 36)
    TitleBar.BackgroundTransparency = 1
    TitleBar.Parent = Main

    local Title = Instance.new("TextLabel")
    Title.RichText = true
    Title.Text = 'Strafe<font color="rgb(255,255,255)">.lua</font>'
    Title.Font = Enum.Font.GothamBlack
    Title.TextSize = 18
    Title.TextColor3 = Theme.Accent
    Title.Size = UDim2.new(1, 0, 1, 0)
    Title.BackgroundTransparency = 1
    Title.TextStrokeTransparency = 0
    Title.TextStrokeColor3 = Color3.new(0, 0, 0)
    Title.Parent = TitleBar

    local TitleLine = Instance.new("Frame")
    TitleLine.Size = UDim2.new(1, 0, 0, 2)
    TitleLine.Position = UDim2.new(0, 0, 1, -2)
    TitleLine.BackgroundColor3 = Theme.Accent
    TitleLine.BorderSizePixel = 0
    TitleLine.Parent = TitleBar

    local FooterLabel = Instance.new("TextLabel")
    FooterLabel.Size = UDim2.new(1, -20, 0, 24)
    FooterLabel.Position = UDim2.new(0, 10, 1, -28)
    FooterLabel.BackgroundTransparency = 1
    FooterLabel.Text = "A 3 second lock will occur when the script loads."
    FooterLabel.Font = Enum.Font.Gotham
    FooterLabel.TextSize = 11
    FooterLabel.TextColor3 = Theme.TextDim
    FooterLabel.TextXAlignment = Enum.TextXAlignment.Center
    FooterLabel.TextWrapped = true
    FooterLabel.Parent = Main

    local dragging, dragStart, startPos
    TitleBar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            dragStart = input.Position
            startPos = Main.Position
        end
    end)
    TitleBar.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end)
    UIS.InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
            local delta = input.Position - dragStart
            Main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)

    local KeyBox = Instance.new("TextBox")
    KeyBox.Size = UDim2.new(1, -30, 0, 32)
    KeyBox.Position = UDim2.new(0, 15, 0, 55)
    KeyBox.BackgroundColor3 = Theme.Item
    KeyBox.BorderSizePixel = 0
    KeyBox.Text = ""
    KeyBox.PlaceholderText = "Enter your key..."
    KeyBox.PlaceholderColor3 = Theme.TextDim
    KeyBox.TextColor3 = Theme.Text
    KeyBox.Font = Enum.Font.Gotham
    KeyBox.TextSize = 14
    KeyBox.ClearTextOnFocus = false
    KeyBox.Parent = Main
    Instance.new("UICorner", KeyBox).CornerRadius = UDim.new(0, 6)

    local KeyStroke = Instance.new("UIStroke", KeyBox)
    KeyStroke.Thickness = 1
    KeyStroke.Color = Theme.Outline

    local Status = Instance.new("TextLabel")
    Status.Size = UDim2.new(1, -30, 0, 18)
    Status.Position = UDim2.new(0, 15, 0, 92)
    Status.BackgroundTransparency = 1
    Status.Text = ""
    Status.Font = Enum.Font.Gotham
    Status.TextSize = 12
    Status.TextColor3 = Theme.TextDim
    Status.TextXAlignment = Enum.TextXAlignment.Left
    Status.Parent = Main

    local GetKeyBtn = Instance.new("TextButton")
    GetKeyBtn.Size = UDim2.new(0.5, -20, 0, 34)
    GetKeyBtn.Position = UDim2.new(0, 15, 0, 120)
    GetKeyBtn.BackgroundColor3 = Theme.Item
    GetKeyBtn.BorderSizePixel = 0
    GetKeyBtn.Text = "Get Key"
    GetKeyBtn.Font = Enum.Font.GothamBold
    GetKeyBtn.TextSize = 14
    GetKeyBtn.TextColor3 = Theme.Text
    GetKeyBtn.AutoButtonColor = false
    GetKeyBtn.Parent = Main
    Instance.new("UICorner", GetKeyBtn).CornerRadius = UDim.new(0, 6)

    local GetKeyStroke = Instance.new("UIStroke", GetKeyBtn)
    GetKeyStroke.Thickness = 1
    GetKeyStroke.Color = Theme.Outline

    local VerifyBtn = Instance.new("TextButton")
    VerifyBtn.Size = UDim2.new(0.5, -20, 0, 34)
    VerifyBtn.Position = UDim2.new(0.5, 5, 0, 120)
    VerifyBtn.BackgroundColor3 = Theme.Accent
    VerifyBtn.BorderSizePixel = 0
    VerifyBtn.Text = "Verify"
    VerifyBtn.Font = Enum.Font.GothamBold
    VerifyBtn.TextSize = 14
    VerifyBtn.TextColor3 = Color3.new(1, 1, 1)
    VerifyBtn.AutoButtonColor = false
    VerifyBtn.Parent = Main
    Instance.new("UICorner", VerifyBtn).CornerRadius = UDim.new(0, 6)

    GetKeyBtn.MouseEnter:Connect(function()
        TS:Create(GetKeyBtn, TweenInfo.new(0.15), {BackgroundColor3 = Theme.Outline}):Play()
    end)
    GetKeyBtn.MouseLeave:Connect(function()
        TS:Create(GetKeyBtn, TweenInfo.new(0.15), {BackgroundColor3 = Theme.Item}):Play()
    end)

    VerifyBtn.MouseEnter:Connect(function()
        TS:Create(VerifyBtn, TweenInfo.new(0.15), {BackgroundColor3 = Color3.fromRGB(170, 190, 235)}):Play()
    end)
    VerifyBtn.MouseLeave:Connect(function()
        TS:Create(VerifyBtn, TweenInfo.new(0.15), {BackgroundColor3 = Theme.Accent}):Play()
    end)

    local function closeUI()
        getgenv().UI_CLOSED = true
        if UI and UI.Parent then
            UI:Destroy()
        end
    end

    GetKeyBtn.MouseButton1Click:Connect(function()
        local link = Junkie.get_key_link()
        if not link then
            Status.Text = "System not initialized"
            Status.TextColor3 = Color3.fromRGB(255, 80, 80)
            return
        end
        local copied = false
        pcall(function()
            if setclipboard then
                setclipboard(link)
                copied = true
            end
        end)
        if not copied then
            pcall(function()
                if toclipboard then
                    toclipboard(link)
                    copied = true
                end
            end)
        end
        if copied then
            Status.Text = "Link copied to clipboard!"
            Status.TextColor3 = Theme.Accent
        else
            Status.Text = tostring(link)
            Status.TextColor3 = Theme.TextDim
        end
    end)

    local verifying = false

    VerifyBtn.MouseButton1Click:Connect(function()
        if verifying then return end
        local key = KeyBox.Text
        if not key or key:gsub("%s+", "") == "" then
            Status.Text = "Enter a key first."
            Status.TextColor3 = Color3.fromRGB(255, 80, 80)
            return
        end

        key = key:gsub("%s+", "")
        verifying = true
        VerifyBtn.Text = "..."
        Status.Text = "Key set. Verifying..."
        Status.TextColor3 = Theme.Accent

        local check = Junkie.check_key(key)

        if check and check.valid then
            saveVerifiedKey(key)
            genv.SCRIPT_KEY = key
            Status.Text = "Verified!"
            Status.TextColor3 = Color3.fromRGB(80, 220, 120)
            task.delay(0.6, function()
                closeUI()
            end)
        else
            Status.Text = "Invalid key"
            Status.TextColor3 = Color3.fromRGB(255, 80, 80)
            VerifyBtn.Text = "Verify"
            verifying = false
        end
    end)

    -- auto check saved / existing key
    local savedKey = loadVerifiedKey()
    local keyToCheck = savedKey
    if not keyToCheck then
        keyToCheck = genv.SCRIPT_KEY
    end

    if keyToCheck and type(keyToCheck) == "string" and keyToCheck ~= "" then
        KeyBox.Text = tostring(keyToCheck)
        Status.Text = "Key already set."
        Status.TextColor3 = Theme.TextDim

        local check = Junkie.check_key(keyToCheck)
        if check and check.valid then
            if check.message == "KEYLESS" then
                Status.Text = "Keyless Mode"
                Status.TextColor3 = Color3.fromRGB(80, 220, 120)
                genv.SCRIPT_KEY = "KEYLESS"
                task.delay(0.5, function()
                    closeUI()
                end)
            elseif check.message == "KEY_VALID" then
                if not savedKey and keyToCheck then
                    saveVerifiedKey(keyToCheck)
                end
                Status.Text = "Verified!"
                Status.TextColor3 = Color3.fromRGB(80, 220, 120)
                genv.SCRIPT_KEY = keyToCheck
                task.delay(0.5, function()
                    closeUI()
                end)
            end
            if savedKey and check and not check.key_valid then
                clearSavedKey()
            end
        end
    end

    while not getgenv().UI_CLOSED do
        task.wait(0.1)
    end
    return getgenv().SCRIPT_KEY
end)()

